const j = $input.first().json;
const body = j.body && typeof j.body === 'object' ? j.body : j;
return [
  {
    json: {
      payload: {
        kind: 'plc_generate',
        project_id: body.project_id,
        requirements: body.requirements || '',
        hardware: body.hardware || 'S7-1200',
        standards: Array.isArray(body.standards) ? body.standards : ['IEC 61131-3'],
      },
      _echo: { project_id: body.project_id, hardware: body.hardware },
    },
  },
];

const r = $input.first().json;
const echo = $('Build_PLC_Payload').first().json._echo || {};
if (r.errors && r.errors.length) {
  throw new Error('Castuo LangGraph: ' + r.errors.join('; '));
}
let plc = '';
let validation = { status: 'REVIEW', messages: [] };
try {
  const o = JSON.parse(r.analysis);
  if (o.plc_code != null) plc = String(o.plc_code);
  if (o.validation && typeof o.validation === 'object') validation = o.validation;
} catch (e) {
  plc = String(r.analysis || '').slice(0, 8000);
}
return [
  {
    json: {
      success: true,
      project_id: echo.project_id,
      hardware: echo.hardware,
      plc_code: plc,
      validation,
      trace_hash: r.trace_hash || '',
      analysis_raw: r.analysis || '',
    },
  },
];
